policy:
{
  // A small, working policy to explore. Change anything and watch the matrix.
  "groups": {
    "group:eng": ["alice@example.com", "bob@example.com"],
  },
  "tagOwners": {
    "tag:web": ["group:eng"],
    "tag:db":  ["group:eng"],
  },
  "grants": [
    // Everyone on the tailnet can reach the web servers over HTTPS.
    { "src": ["autogroup:member"], "dst": ["tag:web"], "ip": ["tcp:443"] },
    // Engineers can reach port 22 on the web servers (SSH needs this and an ssh rule).
    { "src": ["group:eng"], "dst": ["tag:web"], "ip": ["tcp:22"] },
    // The web servers can talk to the database.
    { "src": ["tag:web"], "dst": ["tag:db"], "ip": ["tcp:5432"] },
  ],
  "ssh": [
    // Engineers may SSH to the web servers, after re-authenticating ("check").
    { "action": "check", "src": ["group:eng"], "dst": ["tag:web"], "users": ["autogroup:nonroot"] },
  ],
  "tests": [
    { "src": "carol@example.com", "accept": ["tag:web:443"], "deny": ["tag:db:5432"] },
  ],
}
